-- HANA-SOURCE: cl/bcs/tesoreria/sql/GestionDeDepositos_LiberarComprobanteFormaDePago.sql
-- H2 rewrite: TMMP provides the status list of the forma de pago (scalar subquery); DD/TMMP join -> EXISTS. Params: Id, Entidad.
UPDATE "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP SET "IdEstado" = CASE WHEN INSTR((SELECT MAX(T."EstadosPosibleTipoMovimientoMedioDePago") FROM "BSCL.Tesoreria.BD::TES.TipoMovimientoMedioDePago" AS T WHERE T."IdMedioDePago" = CFP."IdMedioDePago" AND T."IdTipoMovimiento" = CFP."IdTipoMovimiento"), 'CRT') > 0 THEN 'CRT' ELSE 'ING' END, "IdDeposito" = 0, "Depositado" = NULL WHERE EXISTS (SELECT 1 FROM "BSCL.Tesoreria.BD::TES.DepositoDetalle" AS DD INNER JOIN "BSCL.Tesoreria.BD::TES.TipoMovimientoMedioDePago" AS TMMP ON TMMP."IdMedioDePago" = CFP."IdMedioDePago" AND TMMP."IdTipoMovimiento" = CFP."IdTipoMovimiento" WHERE CFP."IdComprobanteFormaDePago" = DD."IdComprobanteFormaDePago" AND :Id = CASE WHEN (:Entidad = 'TES.Deposito') THEN DD."IdDeposito" ELSE DD."IdDepositoDetalle" END)
